<?php
/** خزانه: برگه، اقلام، چک، تسویه و سند در همان قفل شرکت/تراکنش ثبت یا برگردانده می‌شوند. */
namespace Agah\Erp\Modules\Treasury;
use Agah\Erp\Core\{Db,Ctx,Access,Business,Audit,Request,Money,Jalali,Sequence,ValidationException,ConflictException,NotFoundException};
use Agah\Erp\Modules\Accounting\{AccountService,FiscalService,VoucherService};
if(!defined('ABSPATH')) exit;
final class TreasuryService {
    const KINDS=['receipt'=>'دریافت','payment'=>'پرداخت','transfer'=>'انتقال'];
    const CHEQUE_STATES=['pending'=>'در جریان','collected'=>'وصول‌شده','returned'=>'برگشتی','void'=>'باطل'];
    public static function account($cid,$id){Access::need($cid,'treasury_account.view');return Business::row('treasury_accounts',$cid,$id);}
    public static function accounts($cid,$page=1,$q=''){Access::need($cid,'treasury_account.view');return Business::page('treasury_accounts',$cid,$page,$q);}
    /** بانک/صندوق یک تفصیلی انحصاری دارد؛ تغییر ساختار بعد از گردش ممنوع است. */
    public static function saveAccount($cid,$id,array $in){return Access::write($cid,$id?'treasury_account.edit':'treasury_account.create',function()use($cid,$id,$in){
        $old=$id?Business::row('treasury_accounts',$cid,$id,true):null;$kind=$in['kind']??'bank';$name=Request::clean($in['name']??'',190);$code=Money::normDigits($in['code']??'');
        if(!in_array($kind,['bank','cash','petty'],true)||mb_strlen($name)<2||!preg_match('/^[A-Za-z0-9_-]{1,30}$/D',$code))throw new ValidationException(['name'=>'نوع، نام یا کد حساب معتبر نیست.']);
        if(Db::val('SELECT id FROM '.Db::t('treasury_accounts').' WHERE company_id=%d AND code=%s AND id<>%d',$cid,$code,$id))throw new ValidationException(['code'=>'کد حساب خزانه تکراری است.']);
        $iban=strtoupper(Money::normDigits(trim($in['iban']??'')));if($iban!==''&&!self::validIban($iban))throw new ValidationException(['iban'=>'شماره شبای ایران معتبر نیست.']);
        $a=AccountService::bySysKey($cid,$kind==='bank'?'bank':'cash');
        if($old&&$kind!==$old['kind']&&Db::val('SELECT id FROM '.Db::t('voucher_lines').' WHERE company_id=%d AND detail_id=%d LIMIT 1',$cid,$old['detail_id']))throw new ConflictException('نوع حساب دارای گردش تغییر نمی‌کند.');
        $detail=$old?$old['detail_id']:Db::insert('details',['company_id'=>$cid,'code'=>'treasury_'.Sequence::next($cid,'treasury_account',0),'name'=>$name,'kind'=>$kind==='bank'?'bank':'cash','created_at'=>gmdate('Y-m-d H:i:s')]);
        $new=['code'=>$code,'name'=>$name,'kind'=>$kind,'bank_name'=>Request::clean($in['bank_name']??'',100),'account_no'=>Request::clean($in['account_no']??'',40),'iban'=>$iban,'detail_id'=>$detail,'account_id'=>$a['id'],'is_active'=>empty($in['is_active'])?0:1];
        $id=Business::save('treasury_accounts',$cid,$id,$new);Db::update('details',['name'=>$name,'kind'=>$kind==='bank'?'bank':'cash','is_active'=>$new['is_active'],'ref_type'=>'treasury','ref_id'=>$id],['company_id'=>$cid,'id'=>$detail]);Audit::log('treasury.account.save','treasury_account',$id,$old,$new,$cid);return $id;
    });}
    public static function validIban($v){if(!preg_match('/^IR[0-9]{24}$/D',$v))return false;$s=substr($v,4).'1827'.substr($v,2,2);$r=0;foreach(str_split($s) as $c)$r=($r*10+(int)$c)%97;return $r===1;}
    public static function deleteAccount($cid,$id){Access::write($cid,'treasury_account.delete',function()use($cid,$id){$r=Business::row('treasury_accounts',$cid,$id,true);if(Db::val('SELECT id FROM '.Db::t('voucher_lines').' WHERE company_id=%d AND detail_id=%d LIMIT 1',$cid,$r['detail_id'])||Db::val('SELECT id FROM '.Db::t('treasury_doc_items').' WHERE company_id=%d AND treasury_account_id=%d LIMIT 1',$cid,$id)||Db::val('SELECT id FROM '.Db::t('bank_reconciliations').' WHERE company_id=%d AND treasury_account_id=%d LIMIT 1',$cid,$id)||Db::val('SELECT id FROM '.Db::t('import_batches').' WHERE company_id=%d AND treasury_account_id=%d LIMIT 1',$cid,$id))throw new ConflictException('حساب دارای سابقه حذف نمی‌شود؛ غیرفعال کنید.');Db::delete('treasury_accounts',['company_id'=>$cid,'id'=>$id]);Db::delete('details',['company_id'=>$cid,'id'=>$r['detail_id']]);Audit::log('treasury.account.delete','treasury_account',$id,$r,null,$cid);});}
    /** حساب مورد استفاده باید هم در خزانه و هم در کدینگ/تفصیلی فعال باشد. */
    private static function activeAccount($cid,$id){$a=Business::row('treasury_accounts',$cid,$id);if(!$a['is_active'])throw new ValidationException(['account'=>'حساب خزانه غیرفعال است.']);return $a;}
    private static function line($cid,$sys,$detail,$dr,$cr,$description=''){return ['account_id'=>(int)AccountService::bySysKey($cid,$sys)['id'],'detail_id'=>(int)$detail,'debit'=>$dr,'credit'=>$cr,'description'=>$description];}
    private static function accountLine($a,$dr,$cr,$desc=''){return ['account_id'=>(int)$a['account_id'],'detail_id'=>(int)$a['detail_id'],'debit'=>$dr,'credit'=>$cr,'description'=>$desc];}
    /** چرخهٔ این برگه مستقیم issued است؛ پیش از ثبت، تمام اقلام و تخصیص‌ها اعتبارسنجی می‌شوند. */
    public static function issue($cid,array $in,array $items,array $allocations=[]){$kind=$in['kind']??'';if(!isset(self::KINDS[$kind]))throw new ValidationException(['kind'=>'نوع برگه معتبر نیست.']);return Access::write($cid,$kind.'.create',function()use($cid,$kind,$in,$items,$allocations){
        $date=Business::date($in['doc_date']??'');$fy=FiscalService::assertOpen($cid,$date);$party=null;$counterOverride='';$advance=!empty($in['advance']);$description=Request::clean($in['description']??'',500);$total=0;$clean=[];$lines=[];
        $source=null;$target=null;
        if($kind==='transfer'){
            if($allocations||$advance)throw new ValidationException(['settlements'=>'انتقال، شخص و تسویه/پیش‌پرداخت نمی‌پذیرد.']);
            $source=self::activeAccount($cid,Business::id($in['source_account_id']??0));$target=self::activeAccount($cid,Business::id($in['target_account_id']??0));if($source['id']===$target['id'])throw new ValidationException(['target_account_id'=>'مبدأ و مقصد متفاوت باشند.']);
            $total=Business::amount($in['amount']??0,true);$lines=[self::accountLine($target,$total,0,$description),self::accountLine($source,0,$total,$description)];$clean=[['method'=>'transfer','treasury_account_id'=>$source['id'],'amount'=>$total,'reference'=>'']];
        }else{
            if(count($allocations)>100)throw new ValidationException(['settlements'=>'حداکثر صد تخصیص مجاز است.']);
            // استرداد به مشتری: «advance» = برگرداندن پیش‌دریافت (بدهکار پیش‌دریافت)، «customer» = برگرداندن وجه فروش (بدهکار دریافتنی).
            $refund=$kind==='payment'?(string)($in['refund']??''):'';
            if($refund!==''){if(!in_array($refund,['advance','customer'],true)||$advance||($refund==='advance'&&$allocations))throw new ValidationException(['refund'=>'نوع استرداد معتبر نیست.']);$counterOverride=$refund==='advance'?'customer_advances':'receivable';}
            foreach($allocations as $allocation) { $invoice=Business::row('invoices',$cid,Business::id($allocation['invoice_id']??0));$allowed=$kind==='receipt'?['sale'=>'receivable','purchase_return'=>'payable']:['purchase'=>'payable','sale_return'=>'receivable'];if(!isset($allowed[$invoice['kind']]))throw new ValidationException(['settlements'=>'نوع تسویه با دریافت/پرداخت سازگار نیست.']);$candidate=$allowed[$invoice['kind']];if($counterOverride&&$counterOverride!==$candidate)throw new ValidationException(['settlements'=>'تسویه دریافتنی و پرداختنی در یک برگه ترکیب نمی‌شوند.']);$counterOverride=$candidate; }
            $party=Business::row('parties',$cid,Business::id($in['party_id']??0));if(!$party['is_active']||!$party[in_array($counterOverride?:($kind==='receipt'?'receivable':'payable'),['receivable','customer_advances'],true)?'is_customer':'is_supplier'])throw new ValidationException(['party_id'=>'شخص فعال با نقش مشتری/تأمین‌کننده متناسب انتخاب کنید.']);
            if(count($items)<1||count($items)>100)throw new ValidationException(['items'=>'بین یک تا صد قلم وارد کنید.']);
            foreach($items as $i=>$item){if(!is_array($item))throw new ValidationException(['items'=>'قلم معتبر نیست.']);$method=$item['method']??'';if(!in_array($method,['cash','card','transfer','cheque'],true))throw new ValidationException(['items'=>'روش پرداخت معتبر نیست.']);
                $a=self::activeAccount($cid,Business::id($item['treasury_account_id']??0));if(($method==='cash')===($a['kind']==='bank'))throw new ValidationException(['items'=>'وجه نقد برای صندوق/تنخواه و کارت/حواله/چک برای بانک انتخاب شود.']);
                $amount=Business::amount($item['amount']??0,true);$total=Money::add($total,$amount);$row=['method'=>$method,'treasury_account_id'=>(int)$a['id'],'amount'=>$amount,'reference'=>Request::clean($item['reference']??'',80)];
                if($method==='cheque'){$row['due_date']=Business::date($item['due_date']??'');if($row['due_date']<$date)throw new ValidationException(['items.'.$i.'.due_date'=>'تاریخ سررسید چک نمی‌تواند قبل از صدور فاکتور یا برگه باشد.']);$row['cheque_no']=Request::clean($item['cheque_no']??'',80);$row['bank_name']=Request::clean($item['bank_name']??'',100);if($row['cheque_no']==='')throw new ValidationException(['items'=>'شمارهٔ چک الزامی است.']);$line=self::line($cid,$kind==='receipt'?'notes_receivable':'notes_payable',$party['detail_id'],$kind==='receipt'?$amount:0,$kind==='payment'?$amount:0,$description);}
                else $line=self::accountLine($a,$kind==='receipt'?$amount:0,$kind==='payment'?$amount:0,$description);
                $lines[]=$line;$clean[]=$row;
            }
            $counter=$counterOverride?:($kind==='receipt'?($advance?'customer_advances':'receivable'):($advance?'prepayments':'payable'));$lines[]=self::line($cid,$counter,$party['detail_id'],$kind==='payment'?$total:0,$kind==='receipt'?$total:0,$description);
            if(($refund??'')==='advance'){
                $of=Business::row('treasury_docs',$cid,Business::id($in['refund_of_doc_id']??0),true);
                if($of['kind']!=='receipt'||!(int)$of['advance']||$of['status']!=='issued'||(int)$of['party_id']!==(int)$party['id']||$of['doc_date']>$date)throw new ConflictException('برگهٔ پیش‌دریافتِ مبنای استرداد با این شخص و تاریخ سازگار نیست.');
                if($total>self::advanceRemaining($cid,(int)$of['id']))throw new ValidationException(['amount'=>'مبلغ استرداد از ماندهٔ استفاده‌نشدهٔ پیش‌دریافت بیشتر است.']);
                $refundOf=(int)$of['id'];
            }
        }
        $id=Business::save('treasury_docs',$cid,0,['kind'=>$kind,'fiscal_year_id'=>$fy['id'],'number'=>Sequence::next($cid,'treasury_'.$kind,$fy['id']),'doc_date'=>$date,'party_id'=>$party?$party['id']:null,'source_account_id'=>$source?$source['id']:null,'target_account_id'=>$target?$target['id']:null,'advance'=>$advance?1:0,'counter_sys'=>$kind==='transfer'?'':$counter,'amount'=>$total,'description'=>$description,'created_by'=>Ctx::uid(),'refund_of_doc_id'=>$refundOf??null]);
        $stored=[];foreach($clean as $i=>$row){$itemId=Business::save('treasury_doc_items',$cid,0,['doc_id'=>$id,'line_no'=>$i+1,'method'=>$row['method'],'treasury_account_id'=>$row['treasury_account_id'],'amount'=>$row['amount'],'reference'=>$row['reference']]);$stored[]=['id'=>$itemId,'amount'=>$row['amount']];
            if($row['method']==='cheque'){$ch=Business::save('cheques',$cid,0,['doc_id'=>$id,'doc_item_id'=>$itemId,'party_id'=>$party['id'],'treasury_account_id'=>$row['treasury_account_id'],'direction'=>$kind,'cheque_no'=>$row['cheque_no'],'bank_name'=>$row['bank_name'],'due_date'=>$row['due_date'],'amount'=>$row['amount']]);Business::save('cheque_events',$cid,0,['cheque_id'=>$ch,'old_status'=>'','new_status'=>'pending','event_date'=>$date,'reason'=>'صدور برگه','created_by'=>Ctx::uid()]);}
        }
        if($advance&&$allocations)throw new ValidationException(['settlements'=>'پیش‌دریافت/پیش‌پرداخت فعلاً به فاکتور تخصیص داده نمی‌شود.']);
        if($allocations)self::allocate($cid,$id,$kind,$party,$total,$stored,$allocations);
        $vid=VoucherService::postSystem(['voucher_date'=>$date,'description'=>$description?:self::KINDS[$kind],'source_type'=>'treasury_'.$kind,'source_id'=>$id],$lines);Db::update('treasury_docs',['voucher_id'=>$vid],['company_id'=>$cid,'id'=>$id]);Audit::log('treasury.'.$kind.'.issue','treasury_doc',$id,null,['amount'=>$total,'voucher_id'=>$vid],$cid);return $id;
    });}
    /** ماندهٔ استفاده‌نشدهٔ پیش‌دریافت/پیش‌پرداخت = مبلغ − اعمال‌شده به فاکتور − استردادهای صادرشده. */
    public static function advanceRemaining($cid,$docId){
        $d=Business::row('treasury_docs',$cid,$docId);
        $used=(int)Db::val('SELECT COALESCE(SUM(amount),0) FROM '.Db::t('invoice_advances')." WHERE company_id=%d AND doc_id=%d AND status='active'",$cid,$docId);
        $back=(int)Db::val('SELECT COALESCE(SUM(amount),0) FROM '.Db::t('treasury_docs')." WHERE company_id=%d AND refund_of_doc_id=%d AND status='issued'",$cid,$docId);
        return max(0,(int)$d['amount']-$used-$back);
    }
    /**
     * پیوند بعدیِ برگهٔ استرداد به برگشت فروش: وجه پیش‌تر به مشتری برگشته (بدهکار دریافتنی) و برگشت فروش اکنون صادر شده است.
     * سند حسابداری تازه‌ای لازم نیست؛ فقط ردیف تسویه ساخته می‌شود تا مانده و گردش فاکتورها درست بماند.
     */
    public static function linkRefund($cid,$docId,$invoiceId,$amount){
        $d=Business::row('treasury_docs',$cid,$docId,true);$inv=Business::row('invoices',$cid,$invoiceId,true);$amount=(int)$amount;
        if($d['kind']!=='payment'||$d['status']!=='issued'||$d['counter_sys']!=='receivable'||(int)$d['party_id']!==(int)$inv['party_id']||$inv['kind']!=='sale_return'||$inv['status']!=='issued')throw new ConflictException('برگهٔ استرداد با برگشت فروش سازگار نیست.');
        $linked=(int)Db::val('SELECT COALESCE(SUM(amount),0) FROM '.Db::t('settlements')." WHERE company_id=%d AND doc_id=%d AND status='active'",$cid,$docId);
        if($amount<1||$amount>(int)$d['amount']-$linked||$amount>\Agah\Erp\Modules\Trade\InvoiceService::outstanding($cid,$invoiceId))throw new ConflictException('مبلغ پیوند از ماندهٔ برگهٔ استرداد یا برگشت فروش بیشتر است.');
        $items=Db::rows('SELECT id,amount FROM '.Db::t('treasury_doc_items').' WHERE company_id=%d AND doc_id=%d ORDER BY line_no',$cid,$docId);
        foreach($items as $it){if($amount<1)break;$free=(int)$it['amount']-(int)Db::val('SELECT COALESCE(SUM(amount),0) FROM '.Db::t('settlements')." WHERE company_id=%d AND doc_item_id=%d AND status='active'",$cid,$it['id']);$take=min($free,$amount);if($take<1)continue;
            Business::save('settlements',$cid,0,['invoice_id'=>$invoiceId,'doc_id'=>$docId,'doc_item_id'=>(int)$it['id'],'amount'=>$take]);$amount-=$take;}
        Audit::log('treasury.refund.link','treasury_doc',$docId,null,['invoice_id'=>$invoiceId],$cid);
    }
    /** قفل شرکت سقف هم‌زمان دو تسویه را کنترل می‌کند؛ هر تخصیص به قلم منشأ خود پیوند می‌خورد. */
    private static function allocate($cid,$doc,$kind,$party,$total,$items,$allocations){if(count($allocations)>100)throw new ValidationException(['settlements'=>'حداکثر صد تخصیص مجاز است.']);$used=0;$index=0;$remaining=$items[0]['amount'];
        foreach($allocations as $a){if(!is_array($a))throw new ValidationException(['settlements'=>'تخصیص معتبر نیست.']);$amount=Business::amount($a['amount']??0,true);$invoice=Business::row('invoices',$cid,Business::id($a['invoice_id']??0),true);$expected=$invoice['kind'];$allowed=$kind==='receipt'?['sale','purchase_return']:['purchase','sale_return'];
            if((int)$invoice['party_id']!==(int)$party['id']||!in_array($invoice['kind'],$allowed,true)||$invoice['status']!=='issued'||!$invoice['voucher_id'])throw new ValidationException(['settlements'=>'فاکتور صادرشده و هم‌شخص از نوع متناسب لازم است.']);
            $v=Business::row('vouchers',$cid,$invoice['voucher_id']);if(!in_array($v['status'],['approved','final'],true)||$v['source_type']!=='invoice_'.$expected||(int)$v['source_id']!==(int)$invoice['id'])throw new ConflictException('سند فاکتور با منبع آن سازگار نیست.');
            $settled=(int)Db::val('SELECT COALESCE(SUM(amount),0) FROM '.Db::t('settlements')." WHERE company_id=%d AND invoice_id=%d AND status='active'",$cid,$invoice['id']);if($amount>\Agah\Erp\Modules\Trade\InvoiceService::outstanding($cid,(int)$invoice['id']))throw new ValidationException(['settlements'=>'مبلغ تخصیص بیش از ماندهٔ فاکتور است.']);
            $used=Money::add($used,$amount);if($used>$total)throw new ValidationException(['settlements'=>'جمع تخصیص بیش از مبلغ برگه است.']);
            while($amount>0){$take=min($amount,$remaining);Business::save('settlements',$cid,0,['invoice_id'=>$invoice['id'],'doc_id'=>$doc,'doc_item_id'=>$items[$index]['id'],'amount'=>$take]);$amount-=$take;$remaining-=$take;if($remaining===0&&$amount>0){$index++;$remaining=$items[$index]['amount'];}elseif($remaining===0&&isset($items[$index+1])){$index++;$remaining=$items[$index]['amount'];}}
        }
    }
    /** مشاهدهٔ برگه مجوز همان نوع را می‌خواهد؛ تغییر شناسه، نوع دیگری را قابل مشاهده نمی‌کند. */
    public static function get($cid,$id){$r=Business::row('treasury_docs',$cid,$id);Access::need($cid,$r['kind'].'.view');$r['items']=Db::rows('SELECT i.*,a.name account_name FROM '.Db::t('treasury_doc_items').' i JOIN '.Db::t('treasury_accounts').' a ON a.company_id=i.company_id AND a.id=i.treasury_account_id WHERE i.company_id=%d AND i.doc_id=%d ORDER BY i.line_no',$cid,$id);$r['cheques']=Db::rows('SELECT * FROM '.Db::t('cheques').' WHERE company_id=%d AND doc_id=%d',$cid,$id);$r['settlements']=Db::rows('SELECT * FROM '.Db::t('settlements').' WHERE company_id=%d AND doc_id=%d',$cid,$id);return $r;}
    public static function documents($cid,$kind,$page=1,$year=0,array $filters=[]){
        if(!isset(self::KINDS[$kind]))throw new ValidationException(['kind'=>'نوع معتبر نیست.']);Access::need($cid,$kind.'.view');
        $page=max(1,(int)$page);$where='company_id=%d AND kind=%s';$args=[$cid,$kind];if($year){Business::row('fiscal_years',$cid,$year);$where.=' AND fiscal_year_id=%d';$args[]=$year;}
        foreach(['from'=>'>=','to'=>'<='] as $key=>$op)if(!empty($filters[$key])){$where.=' AND doc_date'.$op.'%s';$args[]=Business::date($filters[$key]);}
        if(!empty($filters['q'])){global $wpdb;$like='%'.$wpdb->esc_like(Request::clean($filters['q'],100)).'%';$where.=' AND (CAST(number AS CHAR) LIKE %s OR description LIKE %s OR party_id IN (SELECT id FROM '.Db::t('parties').' WHERE company_id=%d AND name LIKE %s))';array_push($args,$like,$like,$cid,$like);}
        $n=(int)Db::val('SELECT COUNT(*) FROM '.Db::t('treasury_docs').' WHERE '.$where,...$args);return ['rows'=>Db::rows('SELECT * FROM '.Db::t('treasury_docs').' WHERE '.$where.' ORDER BY doc_date DESC,id DESC LIMIT 50 OFFSET %d',...array_merge($args,[($page-1)*50])),'page'=>$page,'pages'=>(int)ceil($n/50),'count'=>$n];
    }

    /** ابطال همهٔ اثرها یا هیچ‌کدام؛ وجود سند قطعیِ مرتبط کل عملیات را rollback می‌کند. */
    public static function voidDocument($cid,$id,$reason){$d=Business::row('treasury_docs',$cid,$id);$cap=\Agah\Erp\Modules\Trade\InvoiceService::allowsDependentReversal($cid,'treasury_doc',$id)?'invoice_delete.delete':$d['kind'].'.delete';Access::write($cid,$cap,function()use($cid,$id,$reason){$d=Business::row('treasury_docs',$cid,$id,true);if($d['status']!=='issued')throw new ConflictException('برگه قبلاً باطل شده است.');$reason=Business::reason($reason);FiscalService::assertOpen($cid,$d['doc_date']);
        if(Db::val('SELECT id FROM '.Db::t('invoice_advances')." WHERE company_id=%d AND doc_id=%d AND status='active' LIMIT 1",$cid,$id))throw new ConflictException('پیش‌پرداخت به فاکتور اعمال شده است؛ ابتدا فاکتور را باطل کنید.');
        if(Db::val('SELECT id FROM '.Db::t('treasury_docs')." WHERE company_id=%d AND refund_of_doc_id=%d AND status='issued' LIMIT 1",$cid,$id))throw new ConflictException('برای این پیش‌دریافت برگهٔ استرداد صادر شده است؛ ابتدا آن را باطل کنید.');
        if(Db::val('SELECT id FROM '.Db::t('connect_refunds').' WHERE company_id=%d AND treasury_doc_id=%d LIMIT 1',$cid,$id))throw new ConflictException('این برگه استرداد ثبت‌شده از فروشگاه است و وجه واقعاً برگشته است؛ ابطال نمی‌شود.');
        $events=Db::rows('SELECT e.* FROM '.Db::t('cheque_events').' e JOIN '.Db::t('cheques').' c ON c.company_id=e.company_id AND c.id=e.cheque_id WHERE e.company_id=%d AND c.doc_id=%d AND e.voucher_id IS NOT NULL ORDER BY e.id DESC',$cid,$id);
        foreach($events as $e)VoucherService::voidSystem($e['voucher_id'],$reason);VoucherService::voidSystem($d['voucher_id'],$reason);
        Db::exec('UPDATE '.Db::t('settlements')." SET status='reversed',updated_at=%s WHERE company_id=%d AND doc_id=%d AND status='active'",gmdate('Y-m-d H:i:s'),$cid,$id);
        foreach(Db::rows('SELECT * FROM '.Db::t('cheques').' WHERE company_id=%d AND doc_id=%d',$cid,$id) as $ch){if($ch['status']!=='void')Business::save('cheque_events',$cid,0,['cheque_id'=>$ch['id'],'old_status'=>$ch['status'],'new_status'=>'void','event_date'=>$d['doc_date'],'reason'=>$reason,'created_by'=>Ctx::uid()]);Db::update('cheques',['status'=>'void','revision'=>(int)$ch['revision']+1,'updated_at'=>gmdate('Y-m-d H:i:s')],['company_id'=>$cid,'id'=>$ch['id']]);}
        Db::update('treasury_docs',['status'=>'void','void_reason'=>$reason,'updated_at'=>gmdate('Y-m-d H:i:s')],['company_id'=>$cid,'id'=>$id]);Audit::log('treasury.void','treasury_doc',$id,$d,['status'=>'void','reason'=>$reason],$cid);
    });}
    /** وضعیت چک فقط با گذار مجاز، نسخهٔ جاری، تاریخ باز و اثر متناظر حسابداری عوض می‌شود. */
    public static function chequeTransition($cid,$id,$status,$date,$reason,$revision){return Access::write($cid,'cheque.approve',function()use($cid,$id,$status,$date,$reason,$revision){
        $c=Business::row('cheques',$cid,$id,true);if((int)$c['revision']!==(int)$revision)throw new ConflictException('وضعیت چک تغییر کرده؛ دوباره باز کنید.');$map=['pending'=>['collected','returned','void'],'collected'=>['returned','void'],'returned'=>['void'],'void'=>[]];if(!in_array($status,$map[$c['status']],true))throw new ConflictException('گذار وضعیت چک مجاز نیست.');
        $date=Business::date($date);$reason=Business::reason($reason);$d=Business::row('treasury_docs',$cid,$c['doc_id']);if($d['status']!=='issued'||$date<$d['doc_date'])throw new ConflictException('برگه باطل است یا تاریخ رویداد قبل از صدور است.');$last=Db::val('SELECT MAX(event_date) FROM '.Db::t('cheque_events').' WHERE company_id=%d AND cheque_id=%d',$cid,$id);if($last&&$date<$last)throw new ValidationException(['date'=>'تاریخ رویداد قبل از رویداد قبلی است.']);FiscalService::assertOpen($cid,$date);
        if(in_array($status,['returned','void'],true)&&Db::val('SELECT id FROM '.Db::t('invoice_advances')." WHERE company_id=%d AND doc_id=%d AND status='active' LIMIT 1",$cid,$c['doc_id']))throw new ConflictException('پیش‌پرداخت به فاکتور اعمال شده است؛ ابتدا فاکتور را باطل کنید.');
        $a=Business::row('treasury_accounts',$cid,$c['treasury_account_id']);$p=Business::row('parties',$cid,$c['party_id']);$amount=(int)$c['amount'];$lines=[];$receipt=$c['direction']==='receipt';
        if($status==='collected')$lines=$receipt?[self::accountLine($a,$amount,0,$reason),self::line($cid,'notes_receivable',$p['detail_id'],0,$amount,$reason)]:[self::line($cid,'notes_payable',$p['detail_id'],$amount,0,$reason),self::accountLine($a,0,$amount,$reason)];
        elseif($c['status']!=='returned'){
            $counter=$d['counter_sys']?:($receipt?($d['advance']?'customer_advances':'receivable'):($d['advance']?'prepayments':'payable'));
            if($receipt)$lines=[self::line($cid,$counter,$p['detail_id'],$amount,0,$reason),$c['status']==='collected'?self::accountLine($a,0,$amount,$reason):self::line($cid,'notes_receivable',$p['detail_id'],0,$amount,$reason)];
            else $lines=[$c['status']==='collected'?self::accountLine($a,$amount,0,$reason):self::line($cid,'notes_payable',$p['detail_id'],$amount,0,$reason),self::line($cid,$counter,$p['detail_id'],0,$amount,$reason)];
        }
        $event=Business::save('cheque_events',$cid,0,['cheque_id'=>$id,'old_status'=>$c['status'],'new_status'=>$status,'event_date'=>$date,'reason'=>$reason,'created_by'=>Ctx::uid()]);
        if($lines){$vid=VoucherService::postSystem(['voucher_date'=>$date,'description'=>$reason,'source_type'=>'cheque_event','source_id'=>$event],$lines);Db::update('cheque_events',['voucher_id'=>$vid],['company_id'=>$cid,'id'=>$event]);}
        if(in_array($status,['returned','void'],true))Db::exec('UPDATE '.Db::t('settlements')." SET status='reversed',updated_at=%s WHERE company_id=%d AND doc_item_id=%d AND status='active'",gmdate('Y-m-d H:i:s'),$cid,$c['doc_item_id']);
        Db::update('cheques',['status'=>$status,'revision'=>(int)$c['revision']+1,'updated_at'=>gmdate('Y-m-d H:i:s')],['company_id'=>$cid,'id'=>$id]);Audit::log('cheque.'.$status,'cheque',$id,$c,['status'=>$status,'event_id'=>$event],$cid);return $event;
    });}
    public static function cheques($cid,$page=1,$status='',$to=''){Access::need($cid,'cheque.view');$where='company_id=%d';$args=[$cid];if($status!==''){if(!isset(self::CHEQUE_STATES[$status]))throw new ValidationException(['status'=>'وضعیت معتبر نیست.']);$where.=' AND status=%s';$args[]=$status;}if($to){$where.=' AND due_date<=%s';$args[]=Business::date($to);}$page=max(1,(int)$page);$n=(int)Db::val('SELECT COUNT(*) FROM '.Db::t('cheques').' WHERE '.$where,...$args);return ['rows'=>Db::rows('SELECT * FROM '.Db::t('cheques').' WHERE '.$where.' ORDER BY due_date,id LIMIT 50 OFFSET %d',...array_merge($args,[($page-1)*50])),'page'=>$page,'pages'=>(int)ceil($n/50),'count'=>$n];}
    /** برگهٔ چاپ چک فقط از دادهٔ همان شرکت و همراه با شخص، حساب خزانه و برگهٔ مبدأ خوانده می‌شود. */
    public static function cheque($cid,$id){Access::need($cid,'cheque.view');$r=Db::row('SELECT c.*,p.name party_name,a.name account_name,d.number doc_number,d.doc_date,d.description FROM '.Db::t('cheques').' c JOIN '.Db::t('parties').' p ON p.company_id=c.company_id AND p.id=c.party_id JOIN '.Db::t('treasury_accounts').' a ON a.company_id=c.company_id AND a.id=c.treasury_account_id JOIN '.Db::t('treasury_docs').' d ON d.company_id=c.company_id AND d.id=c.doc_id WHERE c.company_id=%d AND c.id=%d',$cid,$id);if(!$r)throw new NotFoundException();return $r;}
    /** دفتر خزانه از خطوط حسابداری است، نه جمع مستقل برگه‌ها؛ شامل افتتاحیه و اصلاح دستی مجاز نیز هست. */
    public static function ledger($cid,$account,$to='',$page=1){Access::need($cid,'treasury_account.view');$a=Business::row('treasury_accounts',$cid,$account);$to=$to?:Jalali::today();Business::date($to);$join=' FROM '.Db::t('voucher_lines').' l JOIN '.Db::t('vouchers')." v ON v.company_id=l.company_id AND v.id=l.voucher_id WHERE l.company_id=%d AND l.account_id=%d AND l.detail_id=%d AND v.status IN ('approved','final') AND v.voucher_date<=%s";$args=[$cid,$a['account_id'],$a['detail_id'],$to];$sum=Db::row('SELECT COALESCE(SUM(l.debit),0) debit,COALESCE(SUM(l.credit),0) credit'.$join,...$args);$n=(int)Db::val('SELECT COUNT(*)'.$join,...$args);$page=max(1,(int)$page);return ['account'=>$a,'balance'=>Money::add((int)$sum['debit'],-(int)$sum['credit']),'total'=>$sum,'rows'=>Db::rows('SELECT l.id,l.voucher_id,l.description,l.debit,l.credit,v.number,v.voucher_date'.$join.' ORDER BY v.voucher_date,v.id,l.line_no LIMIT 50 OFFSET %d',...array_merge($args,[($page-1)*50])),'page'=>$page,'pages'=>(int)ceil($n/50)];}
    /** تطبیق سطرهای دفتر با صورتحساب؛ اختلاف از دفتر، اقلام تطبیق‌نشده و ماندهٔ واقعی بانک محاسبه می‌شود. */
    public static function reconcile($cid,$id,array $in,array $matched,$revision=0){return Access::write($cid,'treasury_account.edit',function()use($cid,$id,$in,$matched,$revision){
        $old=$id?Business::row('bank_reconciliations',$cid,$id,true):null;if($old&&(int)$old['revision']!==(int)$revision)throw new ConflictException('مغایرت‌گیری تغییر کرده است.');$a=Business::row('treasury_accounts',$cid,Business::id($in['treasury_account_id']??0));if($a['kind']!=='bank')throw new ValidationException(['account'=>'مغایرت‌گیری فقط حساب بانکی است.']);$date=Business::date($in['as_of_date']??'');$balance=$in['statement_balance']??0;if(!is_int($balance)||$balance < -Money::MAX||$balance>Money::MAX)throw new ValidationException(['statement_balance'=>'ماندهٔ صورتحساب معتبر نیست.']);
        if(Db::val('SELECT id FROM '.Db::t('bank_reconciliations').' WHERE company_id=%d AND treasury_account_id=%d AND as_of_date=%s AND id<>%d',$cid,$a['id'],$date,$id))throw new ConflictException('برای این بانک و تاریخ مغایرت‌گیری وجود دارد؛ همان را ویرایش کنید.');
        if(count($matched)>2000)throw new ValidationException(['matched'=>'حداکثر دو هزار ردیف در هر درخواست.']);$ids=array_values(array_unique(array_map([Business::class,'id'],$matched)));
        foreach($ids as $line){$r=Db::row('SELECT l.id FROM '.Db::t('voucher_lines').' l JOIN '.Db::t('vouchers')." v ON v.company_id=l.company_id AND v.id=l.voucher_id WHERE l.company_id=%d AND l.id=%d AND l.account_id=%d AND l.detail_id=%d AND v.status IN ('approved','final') AND v.voucher_date<=%s",$cid,$line,$a['account_id'],$a['detail_id'],$date);if(!$r)throw new NotFoundException();}
        $new=['treasury_account_id'=>$a['id'],'as_of_date'=>$date,'statement_balance'=>$balance,'notes'=>Request::clean($in['notes']??'',500),'revision'=>(int)($old['revision']??0)+1];$id=Business::save('bank_reconciliations',$cid,$id,$new);Db::delete('bank_reconciliation_items',['company_id'=>$cid,'reconciliation_id'=>$id]);foreach($ids as $line)Business::save('bank_reconciliation_items',$cid,0,['reconciliation_id'=>$id,'voucher_line_id'=>$line]);Audit::log('treasury.reconcile','reconciliation',$id,$old,$new+['matched'=>$ids],$cid);return $id;
    });}
    /** نتیجه زنده بازحساب می‌شود؛ ثبت مغایرت‌گیری ادعای قفل/قطعی‌بودن اسناد دفتر نیست. */
    public static function reconciliation($cid,$id){Access::need($cid,'treasury_account.view');$r=Business::row('bank_reconciliations',$cid,$id);$ledger=self::ledger($cid,$r['treasury_account_id'],$r['as_of_date']);$a=$ledger['account'];$matched=Db::rows('SELECT m.voucher_line_id,l.debit,l.credit FROM '.Db::t('bank_reconciliation_items').' m JOIN '.Db::t('voucher_lines').' l ON l.company_id=m.company_id AND l.id=m.voucher_line_id JOIN '.Db::t('vouchers')." v ON v.company_id=l.company_id AND v.id=l.voucher_id WHERE m.company_id=%d AND m.reconciliation_id=%d AND l.account_id=%d AND l.detail_id=%d AND v.status IN ('approved','final') AND v.voucher_date<=%s",$cid,$id,$a['account_id'],$a['detail_id'],$r['as_of_date']);$cleared=0;foreach($matched as $m)$cleared=Money::add($cleared,Money::add((int)$m['debit'],-(int)$m['credit']));return ['record'=>$r,'ledger'=>$ledger,'matched'=>array_map('intval',array_column($matched,'voucher_line_id')),'unmatched'=>Money::add($ledger['balance'],-$cleared),'cleared'=>$cleared,'difference'=>Money::add($cleared,-(int)$r['statement_balance'])];}
    /** پیش‌بینی صرفاً از چک‌های در جریان و سررسید فاکتورهای صادرشدهٔ تسویه‌نشده؛ تاریخ و مبلغ واقعی. */
    public static function forecast($cid,$to){Access::need($cid,'treasury_account.view');Business::date($to);$accounts=Db::rows('SELECT id FROM '.Db::t('treasury_accounts').' WHERE company_id=%d',$cid);$balance=0;foreach($accounts as $a)$balance=Money::add($balance,self::ledger($cid,$a['id'])['balance']);$cheques=Db::rows('SELECT id,direction,due_date,amount FROM '.Db::t('cheques')." WHERE company_id=%d AND status='pending' AND due_date<=%s ORDER BY due_date,id",$cid,$to);$expected=$balance;foreach($cheques as $c)$expected=Money::add($expected,$c['direction']==='receipt'?(int)$c['amount']:-(int)$c['amount']);$invoices=Db::rows('SELECT i.id,i.kind,i.due_date,i.amount-COALESCE(s.settled,0) outstanding FROM '.Db::t('invoices')." i LEFT JOIN (SELECT company_id,invoice_id,SUM(amount) settled FROM ".Db::t('settlements')." WHERE company_id=%d AND status='active' GROUP BY company_id,invoice_id) s ON s.company_id=i.company_id AND s.invoice_id=i.id WHERE i.company_id=%d AND i.status='issued' AND i.kind IN ('sale','purchase','sale_return','purchase_return') AND i.due_date<=%s AND i.amount>COALESCE(s.settled,0) ORDER BY i.due_date,i.id",$cid,$cid,$to);foreach($invoices as &$i)$i['outstanding']=\Agah\Erp\Modules\Trade\InvoiceService::outstanding($cid,(int)$i['id']);unset($i);$invoices=array_values(array_filter($invoices,function($i){return $i['outstanding']>0;}));foreach($invoices as $i)$expected=Money::add($expected,in_array($i['kind'],['sale','purchase_return'],true)?(int)$i['outstanding']:-(int)$i['outstanding']);return ['current'=>$balance,'expected'=>$expected,'cheques'=>$cheques,'invoices'=>$invoices,'to'=>$to];}
}
